package com.ayuemin.ymnik

/**
 * First-stage prompt diet for the primary chat model.
 *
 * Kotlin resolves a same-package extension before the default-imported appendLine extension,
 * so ChatViewModel's existing buildString blocks pass their String lines through here without
 * rewriting the large ViewModel file. Only exact, known prompt lines are compacted; every other
 * String line is emitted unchanged. The Local Shell worker is intentionally not dieted here.
 */
internal fun StringBuilder.appendLine(value: String): StringBuilder {
    val compact = compactPrimaryPromptLine(value)
    if (compact != null) append(compact).append('\n')
    return this
}

private fun compactPrimaryPromptLine(value: String): String? = when (value) {
    "Ты работаешь внутри Android-приложения «Umnik». Отвечай на языке пользователя, если он не попросил иначе." ->
        "Ты работаешь в Android-приложении Umnik. Отвечай на языке пользователя, если не попросили иначе."
    "Считай текущий запрос продолжением этого диалога. Ссылки вроде «это», «предыдущий текст», «эта статья», «второй вариант», «сделай короче» относятся к уже переданной истории или памяти чата, если из контекста понятно, о чём речь." ->
        "Считай запрос продолжением диалога; ссылки вроде «это», «предыдущий текст», «второй вариант», «сделай короче» соотноси с историей или памятью по контексту."
    "Не проси пользователя повторно прислать материал, если нужный текст, результат или сведения уже присутствуют в переданной истории, долговременной памяти, базе знаний или приложенных файлах." ->
        "Не проси повторно присылать материал, уже доступный в истории, памяти, базе знаний или файлах."
    "Если пользователь просит точно прочитать или переписать текст с изображения, не достраивай неразборчивые слова по смыслу. Помечай неуверенные места и не выдавай предположение за точную расшифровку." ->
        "При точной переписи текста с изображения не додумывай неразборчивое; отмечай неуверенные места."

    "Агентный режим этого чата выключен. Не инициируй Browser или Local Shell самостоятельно. Если они могли бы заметно упростить задачу, можешь кратко предложить пользователю включить «Агент» или прямо попросить нужный инструмент." ->
        "Агентный режим выключен: не запускай Browser или Local Shell сам. Если они заметно упростят задачу, можешь кратко предложить включить «Агент» или попросить нужный инструмент."
    "Если Browser или Local Shell всё же доступен среди инструментов текущего запроса, это означает явное разрешение пользователя: он прямо попросил этот инструмент либо выбрал соответствующий режим. В таком случае выполняй задачу без повторного согласования и не спорь с выбором пользователя." ->
        "Если Browser или Local Shell всё же доступны среди tools, пользователь уже разрешил их; выполняй без повторного согласования."

    "Инструмент create_file доступен только для явно запрошенного файлового результата. Используй его, если пользователь прямо просит файл/скачивание либо подключённая инструкция явно требует вернуть результат файлом." ->
        "create_file используй только когда пользователь или подключённая инструкция явно требуют файловый результат."
    "Не утверждай, что создал скачиваемый файл: в этом запросе инструмент создания файла не подключён." ->
        "Не утверждай, что создал скачиваемый файл, если create_file недоступен."
    // The same rule is already emitted earlier in buildSystemPrompt when create_file is enabled.
